args.CommandLine:
"swift -e '
import AppKit

guard let image = NSImage(contentsOfFile: "/Users/scappin/Desktop/Workspace.png"),
      let tiff = image.tiffRepresentation,
      let rep = NSBitmapImageRep(data: tiff) else {
    print("Could not load image")
    exit(1)
}

let width = rep.pixelsWide
let height = rep.pixelsHigh

guard let bitmapData = rep.bitmapData else {
    print("Could not get bitmap data")
    exit(1)
}

let bpp = rep.bitsPerPixel / 8
let rowBytes = rep.bytesPerRow

for y in 0..<height {
    for x in 0..<width {
        let offset = y * rowBytes + x * bpp
        let r = Double(bitmapData[offset])
        let g = Double(bitmapData[offset + 1])
        let b = Double(bitmapData[offset + 2])

        // Check whiteness
        if r > 240 && g > 240 && b > 240 {
            if bpp == 4 {
                bitmapData[offset + 3] = 0 // Fully transparent
            }
        } else if r > 215 && g > 215 && b > 215 {
            if bpp == 4 {
                let brightness = (r + g + b) / 3.0
                let alpha = UInt8(max(0, min(255, 255.0 * (1.0 - (brightness - 215.0) / (255.0 - 215.0)))))
                bitmapData[offset + 3] = alpha
            }
        }
    }
}

if let pngData = rep.representation(using: .png, properties: [:]) {
    try? pngData.write(to: URL(fileURLWithPath: "/Users/scappin/Src/ACE/Workspace.png"))
    print("Successfully processed Workspace.png with transparency")
}
'"

