  z-index: 100;
  transition: transform 0.15s ease-out, filter 0.2s ease;
  user-select: none;
}

.draggable-item:hover {
  transform: scale(1.04);
}

.draggable-item.dragging {
  cursor: grabbing;
  transform: scale(1.08);
  transition: none;
  z-index: 105;
}

