"      // 3. Machined Outer Bevel Border
      ctx.lineWidth = 2.5;
      ctx.strokeStyle = 'rgba(0, 240, 255, 0.45)';
      ctx.stroke();

      // 4. Heavy Horizontal Foundation Base Beam
      const beamW = baseW + 36;
      const beamH = 14;
      const beamY = footY;

      const beamGrad = ctx.createLinearGradient(x, beamY, x, beamY + beamH);
      beamGrad.addColorStop(0, '#1c2638');
      beamGrad.addColorStop(1, '#0e1420');

      ctx.fillStyle = beamGrad;
      ctx.strokeStyle = 'rgba(0, 240, 255, 0.6)';
      ctx.lineWidth = 1.8;
      ctx.shadowColor = 'rgba(0, 240, 255, 0.35)';
      ctx.shadowBlur = 8;

      ctx.beginPath();
      if (ctx.roundRect) {
        ctx.roundRect(x - beamW / 2, beamY, beamW, beamH, 4);
      } else {
        ctx.rect(x - beamW / 2, beamY, beamW, beamH);
      }
      ctx.fill();
      ctx.stroke();

      // Clear Shadow
