  const LayoutManager = {
    items: [],
    masterDefaults: null,

    register(item) {
      this.items.push(item);
    },

    async loadMasterDefaults() {
      try {
        const res = await fetch('default_positions.json?t=' + Date.now());
        if (res.ok) {
          this.masterDefaults = await res.json();
          this.applyMasterDefaults();
        }
      } catch (e) {}
    },

    applyMasterDefaults() {
      if (!this.masterDefaults) return;
      this.items.forEach(item => {
        const saved = localStorage.getItem(item.storageKey);
        if (!saved && this.masterDefaults[item.elementId]) {
          const pos = this.masterDefaults[item.elementId];
          item.setPosition(pos.left, pos.top, false);
        }
      });
    },

