      const payload = {};
      this.items.forEach(item => {
        const rect = item.el.getBoundingClientRect();
        payload[item.elementId] = {
          left: Math.round(rect.left),
          top: Math.round(rect.top),
          storageKey: item.storageKey
        };
      });

