"  const LayoutManager = {
    items: [],
    masterDefaults: null,

    register(item) {
      this.items.push(item);
    },

    async loadMasterDefaults() {
      try {
        const res = await fetch('default_positions.json?t=' + Date.now());
        if (res.ok) {
          this.masterDefaults = await res.json();
          this.applyMasterDefaults();
        }
      } catch (e) {}
    },

    applyMasterDefaults() {
      if (!this.masterDefaults) return;
      this.items.forEach(item => {
        const saved = localStorage.getItem(item.storageKey);
        if (!saved && this.masterDefaults[item.elementId]) {
          const pos = this.masterDefaults[item.elementId];
          item.setPosition(pos.left, pos.top, false);
        }
      });
    },

    syncCurrentToMaster() {
      const payload = {};
      this.items.forEach(item => {
        const rect = item.el.getBoundingClientRect();
        payload[item.elementId] = {
          left: Math.round(rect.left),
          top: Math.round(rect.top),
          storageKey: item.storageKey
        };
      });

      console.log('[LayoutManager] Syncing current master layout payload:', payload);

      fetch('/api/save-layout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      }).then(r => r.json()).then(data => {
        console.log('[LayoutManager] Master layout synced successfully to server:', data);
        const toast = document.getElementById('sync-toast');
        if (toast) {
          toast.innerHTML = '<strong>✓ Master Layout Saved!</strong><br>Incognito and all other browsers will now load this exact layout.';
          toast.classList.add('visible');
          setTimeout(() => toast.classList.remove('visible'), 5000);
        }
      }).catch(err => {
        console.error('[LayoutManager] Error saving master layout:', err);
        alert('Layout saved locally. (Server sync error: ' + err.message + ')');
      });

